use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let input = from_str(&input.to_string()).unwrap();
    let mut result = Vec::new();

    for (left, right) in input.as_array().unwrap().iter().cloned() {
        let mut left_map = std::collections::HashMap::new();
        let mut right_map = std::collections::HashMap::new();

        for row in left {
            left_map.insert(row[0].as_i64().unwrap(), row[1].as_i64().unwrap());
        }

        for row in right {
            right_map.insert(row[0].as_i64().unwrap(), row[1].as_i64().unwrap());
        }

        let common_keys = left_map.keys().intersection(&right_map.keys()).cloned().collect::<Vec<_>>();

        common_keys.sort_unstable();

        for key in common_keys {
            let left_value = left_map.get(key).unwrap();
            let right_value = right_map.get(key).unwrap();
            result.push(vec![key, *left_value, *right_value]);
        }
    }

    Value::Array(result)
}
